-- Generated by scripts/generate-private-value-sql.mjs from shared language data.
-- Grouping/decimal ambiguity and wrappers mirror numeric()/scalar() in JS.
create function app.private_invoice_number_aliases(p_term text) returns setof text
language plpgsql immutable set search_path='' as $$
declare
  term text := app.private_invoice_normalize(p_term);
  whole text; fraction text; groups text[]; valid boolean; i integer; prior text;
  multiplier numeric:=1; unit_pattern text := '(?:inr|usd|eur|gbp|aed|sgd|aud|cad|chf|rs\.?|rupees?|dollars?|euros?|pounds?)';
begin
  term:=regexp_replace(term,U&'^[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]+|[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]+$','','g');
  term:=regexp_replace(term,'^\((.*)\)$','\1');
  term:=regexp_replace(term,U&'[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]',chr(39),'g');
  loop
    prior:=term;
    term:=btrim(regexp_replace(term,'^(?:[+−-]|'||U&'[\0024\00a2-\00a5\058f\060b\07fe-\07ff\09f2-\09f3\09fb\0af1\0bf9\0e3f\17db\20a0-\20c1\a838\fdfc\fe69\ff04\ffe0-\ffe1\ffe5-\ffe6\+011fdd-\+011fe0\+01e2ff\+01ecb0]'||'|'||unit_pattern||') *| *(?:'||U&'[\0024\00a2-\00a5\058f\060b\07fe-\07ff\09f2-\09f3\09fb\0af1\0bf9\0e3f\17db\20a0-\20c1\a838\fdfc\fe69\ff04\ffe0-\ffe1\ffe5-\ffe6\+011fdd-\+011fe0\+01e2ff\+01ecb0]'||'|'||unit_pattern||')$','','g'));
    exit when term=prior;
  end loop;
  term:=regexp_replace(term,'[.,]+$','');
  if term ~ '[kmb]$' then
    multiplier:=case right(term,1) when 'k' then 1000 when 'm' then 1000000 else 1000000000 end;
    term:=btrim(left(term,length(term)-1));
  end if;
  term:=regexp_replace(term,' *([.,'']) *','\1','g');
  if term !~ '^[0-9]+([.,'' ][0-9]+)*$' then return; end if;
  for i in 1..2 loop
    fraction:='';whole:=term;
    if i=2 then
      if term !~ '[.,][0-9]+$' then continue; end if;
      fraction:=substring(term from '[.,]([0-9]+)$');whole:=regexp_replace(term,'[.,][0-9]+$','');
    end if;
    groups:=regexp_split_to_array(whole,'[.,'' ]');valid:=cardinality(groups)=1;
    if not valid and length(groups[1]) between 1 and 3 then
      valid:=not exists(select 1 from unnest(groups[2:cardinality(groups)]) g where length(g)<>3);
    end if;
    if not valid and length(groups[1]) between 1 and 2 and length(groups[cardinality(groups)])=3 then
      valid:=not exists(select 1 from unnest(groups[2:cardinality(groups)-1]) g where length(g)<>2);
    end if;
    if valid then return next 'number:'||trim_scale((array_to_string(groups,'')||case when fraction<>'' then '.'||fraction else '' end)::numeric*multiplier)::text;end if;
  end loop;
end $$;
revoke all on function app.private_invoice_number_aliases(text) from public,anon,authenticated,service_role;

-- The same strict group grammar as JS: one atom, tens+unit, or a hundred group.
create function app.private_invoice_group_number(words text[]) returns numeric
language plpgsql immutable set search_path='' as $$
declare small jsonb:='{"zero":"0","one":"1","two":"2","three":"3","four":"4","five":"5","six":"6","seven":"7","eight":"8","nine":"9","ten":"10","eleven":"11","twelve":"12","thirteen":"13","fourteen":"14","fifteen":"15","sixteen":"16","seventeen":"17","eighteen":"18","nineteen":"19","twenty":"20","thirty":"30","forty":"40","fifty":"50","sixty":"60","seventy":"70","eighty":"80","ninety":"90"}'::jsonb; n integer:=cardinality(words); h integer; a numeric; b numeric;
begin
  if n=0 then return 0;end if;
  h:=array_position(words,'hundred');
  if h is not null then
    if array_position(words[h+1:n],'hundred') is not null then return null;end if;
    a:=case when h=1 then 1 else app.private_invoice_group_number(words[1:h-1]) end;
    b:=app.private_invoice_group_number(words[h+1:n]);
    return case when a>0 and a<100 and b>=0 and b<100 then a*100+b else null end;
  end if;
  if n=1 then
    if small ? words[1] then return (small->>words[1])::numeric;end if;
    return (select substring(k from 8)::numeric from app.private_invoice_number_aliases(words[1]) k where k ~ '^number:[0-9]+$' limit 1);
  end if;
  if n<>2 then return null;end if;
  a:=app.private_invoice_group_number(words[1:1]);b:=app.private_invoice_group_number(words[2:2]);
  return case when a between 20 and 90 and mod(a,10)=0 and b>0 and b<10 then a+b else null end;
end $$;
revoke all on function app.private_invoice_group_number(text[]) from public,anon,authenticated,service_role;

create function app.private_invoice_word_number_value(words text[]) returns setof text
language plpgsql immutable set search_path='' as $$
declare
  small jsonb:='{"zero":"0","one":"1","two":"2","three":"3","four":"4","five":"5","six":"6","seven":"7","eight":"8","nine":"9","ten":"10","eleven":"11","twelve":"12","thirteen":"13","fourteen":"14","fifteen":"15","sixteen":"16","seventeen":"17","eighteen":"18","nineteen":"19","twenty":"20","thirty":"30","forty":"40","fifty":"50","sixty":"60","seventy":"70","eighty":"80","ninety":"90"}'::jsonb; scales jsonb:='{"thousand":"1000","lakh":"100000","lac":"100000","million":"1000000","crore":"10000000","billion":"1000000000"}'::jsonb; fractions jsonb:='{"half":"2","halves":"2","quarter":"4","quarters":"4"}'::jsonb;
  factor numeric; split_at integer; base_key text; numerator_key text; head text[]; tail_words text[];
  word text; total numeric:=0; part numeric; tail numeric; last_scale numeric; start_at integer:=1; i integer;
  actual text[]; point integer;
begin
  if cardinality(words)=0 or not exists(select 1 from unnest(words) w where w not in ('and','a')) then return;end if;
  if cardinality(words)=1 then
    return query select * from app.private_invoice_number_aliases(words[1]);
    if found then return;end if;
  end if;
  factor:=coalesce((scales->>words[cardinality(words)])::numeric,case when words[cardinality(words)]='hundred' then 100 else 1 end);
  if factor<>1 and exists(select 1 from unnest(words) w where w='point' or fractions ? w or w ~ '^[0-9]+[.,][0-9]+$') then
    return query select 'number:'||trim_scale(substring(alias from 8)::numeric*factor)::text
      from app.private_invoice_word_number_value(words[1:cardinality(words)-1]) alias;return;
  end if;
  if fractions ? words[cardinality(words)] then
    split_at:=(select max(n) from unnest(words) with ordinality p(w,n) where w='and');
    head:=case when split_at is null then array['zero'] else words[1:split_at-1] end;
    tail_words:=array_remove(words[coalesce(split_at+1,1):cardinality(words)-1],'a');
    if cardinality(tail_words)=0 then tail_words:=array['one'];end if;
    for base_key in select * from app.private_invoice_word_number_value(head) loop
      for numerator_key in select * from app.private_invoice_word_number_value(tail_words) loop
        if numerator_key ~ '^number:[0-9]+$' then return next 'number:'||trim_scale(substring(base_key from 8)::numeric+substring(numerator_key from 8)::numeric/(fractions->>words[cardinality(words)])::numeric)::text;end if;
      end loop;
    end loop;return;
  end if;
  point:=array_position(words,'point');
  if point is not null then
    tail_words:=words[point+1:cardinality(words)];
    if cardinality(tail_words)=0 or exists(select 1 from unnest(tail_words) w where w !~ '^[0-9]+$' and (not small ? w or (small->>w)::numeric>9)) then return;end if;
    for base_key in select * from app.private_invoice_word_number_value(words[1:point-1]) loop
      return next 'number:'||trim_scale((substring(base_key from 8)||'.'||(select string_agg(case when w ~ '^[0-9]+$' then w else small->>w end,'' order by n) from unnest(tail_words) with ordinality p(w,n)))::numeric)::text;
    end loop;return;
  end if;
  actual:=array_remove(array_remove(words,'and'),'a');
  if cardinality(actual)>=2 and array_position(words,'and') is null and not exists(select 1 from unnest(actual) w where not small ? w or (small->>w)::numeric>9) then
    return next 'number:'||trim_scale((select string_agg(small->>w,'' order by n) from unnest(actual) with ordinality p(w,n))::numeric)::text;return;
  end if;
  if cardinality(actual) between 2 and 3 and not exists(select 1 from unnest(actual) w where app.private_invoice_group_number(array[w]) is null) then
    part:=app.private_invoice_group_number(actual[1:1]);tail:=app.private_invoice_group_number(actual[2:cardinality(actual)]);
    if part>0 and part<100 and tail>=10 and tail<100 then return next 'number:'||trim_scale(part*100+tail)::text;return;end if;
  end if;
  for i in 1..cardinality(actual) loop
    if scales ? actual[i] then
      factor:=(scales->>actual[i])::numeric;
      part:=case when start_at=i then 1 else app.private_invoice_group_number(actual[start_at:i-1]) end;
      if part is null or last_scale is not null and (factor>=last_scale or part>=last_scale) then return;end if;
      total:=total+part*factor;last_scale:=factor;start_at:=i+1;
    end if;
  end loop;
  tail:=app.private_invoice_group_number(actual[start_at:cardinality(actual)]);
  if tail is null or last_scale is not null and tail>=last_scale then return;end if;
  return next 'number:'||trim_scale(total+tail)::text;
end $$;
revoke all on function app.private_invoice_word_number_value(text[]) from public,anon,authenticated,service_role;

create function app.private_invoice_word_number_aliases(p_term text) returns setof text
language plpgsql immutable set search_path='' as $$
declare
  small jsonb:='{"zero":"0","one":"1","two":"2","three":"3","four":"4","five":"5","six":"6","seven":"7","eight":"8","nine":"9","ten":"10","eleven":"11","twelve":"12","thirteen":"13","fourteen":"14","fifteen":"15","sixteen":"16","seventeen":"17","eighteen":"18","nineteen":"19","twenty":"20","thirty":"30","forty":"40","fifty":"50","sixty":"60","seventy":"70","eighty":"80","ninety":"90"}'::jsonb; scales jsonb:='{"thousand":"1000","lakh":"100000","lac":"100000","million":"1000000","crore":"10000000","billion":"1000000000"}'::jsonb; fractions jsonb:='{"half":"2","halves":"2","quarter":"4","quarters":"4"}'::jsonb;
  token text[]; word text; words text[]:=array[]::text[]; segment text[]; start_at integer:=1; end_at integer; segment_end integer; piece integer; keys text[];
begin
  for token in select regexp_matches(app.private_invoice_normalize(p_term),'[0-9]+(?:[.,'' ]+[0-9]+)*|[a-z]+|[, &-]+|[^ ]','g') loop
    word:=token[1];
    if word ~ '^[, &-]+$' then
      if word ~ '[,&]' then words:=array_append(words,'and');end if;continue;
    end if;
    if small ? word or scales ? word or fractions ? word or word in ('hundred','and','a','point') then
      null;
    elsif not exists(select 1 from app.private_invoice_number_aliases(word)) then
      if word ~ '[a-z]' then return;end if;word:='!';
    end if;
    words:=array_append(words,word);
  end loop;
  while start_at<=cardinality(words) loop
    segment_end:=coalesce((select min(n)::integer from unnest(words) with ordinality p(w,n) where n>=start_at and w='!'),cardinality(words)+1)-1;
    segment:=words[start_at:segment_end];piece:=1;
    if exists(select 1 from unnest(segment) w where (small ? w or scales ? w or fractions ? w or w in ('hundred','point'))) then
      while piece<=cardinality(segment) loop
        end_at:=cardinality(segment);
        while end_at>=piece loop
          keys:=array(select k from app.private_invoice_word_number_value(segment[piece:end_at]) k);
          exit when cardinality(keys)>0;end_at:=end_at-1;
        end loop;
        if end_at<piece then piece:=piece+1;continue;end if;
        return query select unnest(keys);piece:=end_at+1;
      end loop;
    end if;
    start_at:=segment_end+2;
  end loop;
end $$;
revoke all on function app.private_invoice_word_number_aliases(text) from public,anon,authenticated,service_role;

create function app.private_invoice_term_aliases(p_term text) returns setof text
language plpgsql immutable set search_path='' as $$
declare
  term text:=app.private_invoice_normalize(p_term);parts text[];y integer;m integer;day integer;d date;candidate integer[];
  ordinals text[]:=string_to_array('first,second,third,fourth,fifth,sixth,seventh,eighth,ninth,tenth,eleventh,twelfth,thirteenth,fourteenth,fifteenth,sixteenth,seventeenth,eighteenth,nineteenth,twentieth,twenty first,twenty second,twenty third,twenty fourth,twenty fifth,twenty sixth,twenty seventh,twenty eighth,twenty ninth,thirtieth,thirty first',',');month_pattern text:='(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)';
  day_pattern text;day_text text;month_text text;canonical text;date_term text;has_dates boolean:=false;
  candidates integer[][]:=array[]::integer[][];
begin
  if length(term) not between 1 and 4000 then return;end if;
  return next term;
  term:=regexp_replace(term,U&'^[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]+|[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]+$','','g');
  return query select * from app.private_invoice_number_aliases(term);
  return query select * from app.private_invoice_word_number_aliases(term);
  date_term:=regexp_replace(term,'[., ]+$','');
  parts:=regexp_match(date_term,'^([0-9]{4}) *[./-] *([0-9]{1,2}) *[./-] *([0-9]{1,2})$');
  if parts is not null then candidates:=array[array[parts[1]::integer,parts[2]::integer,parts[3]::integer]];
  else
    parts:=regexp_match(date_term,'^([0-9]{1,2}) *[./-] *([0-9]{1,2})(?: *[./-] *([0-9]{4}|[0-9]{2}))?$');
    if parts is not null then
      y:=parts[3]::integer;
      if length(parts[3])=2 then y:=y+case when y<=69 then 2000 else 1900 end;end if;
      candidates:=array[array[y,parts[2]::integer,parts[1]::integer],array[y,parts[1]::integer,parts[2]::integer]];
    else
      parts:=regexp_match(date_term,'^(?:the +)?((?:[0-9]{1,2}(?:st|nd|rd|th)?|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth|twenty[ -]+first|twenty[ -]+second|twenty[ -]+third|twenty[ -]+fourth|twenty[ -]+fifth|twenty[ -]+sixth|twenty[ -]+seventh|twenty[ -]+eighth|twenty[ -]+ninth|thirtieth|thirty[ -]+first))[ ./-]*(?:of +)?((?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?))(?:[ ,./-]*[''’ʼ]? *([0-9]{4}|[0-9]{2}|[0-9]{1,3}))?$');
      if parts is not null then day_text:=parts[1];month_text:=parts[2];y:=parts[3]::integer;
      else
        parts:=regexp_match(date_term,'^((?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?))[ ./-]*(?:the +)?((?:[0-9]{1,2}(?:st|nd|rd|th)?|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth|twenty[ -]+first|twenty[ -]+second|twenty[ -]+third|twenty[ -]+fourth|twenty[ -]+fifth|twenty[ -]+sixth|twenty[ -]+seventh|twenty[ -]+eighth|twenty[ -]+ninth|thirtieth|thirty[ -]+first))(?:[ ,./-]*[''’ʼ]? *([0-9]{4}|[0-9]{2}|[0-9]{1,3}))?$');
        if parts is not null then month_text:=parts[1];day_text:=parts[2];y:=parts[3]::integer;end if;
      end if;
      if parts is not null then
        if length(parts[3])=2 then y:=y+case when y<=69 then 2000 else 1900 end;end if;
        m:=array_position(array['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'],left(month_text,3));
        if day_text ~ '^[0-9]' then day:=regexp_replace(day_text,'(st|nd|rd|th)$','')::integer;
        else day:=array_position(ordinals,regexp_replace(day_text,'[ -]+',' ','g'));end if;
        candidates:=array[array[y,m,day]];
      end if;
    end if;
  end if;
  if cardinality(candidates)>0 then
  foreach candidate slice 1 in array candidates loop
    y:=candidate[1];m:=candidate[2];day:=candidate[3];
    begin d:=make_date(coalesce(y,2000),m,day);exception when datetime_field_overflow or invalid_datetime_format then continue;end;
    has_dates:=true;return next 'date:'||case when y is null then '*' else lpad(y::text,4,'0') end||to_char(d,'-MM-DD');
  end loop;
  end if;
  -- Identifier aliases contain no separator-dependent spelling. SQL uses the
  -- same normalized alphanumeric characters; JS inserts separator wildcards.
  if not has_dates and not exists(select 1 from app.private_invoice_number_aliases(term)) and not exists(select 1 from app.private_invoice_word_number_aliases(term))
    and term ~ '[[:alpha:]]' and term !~ '[^[:alnum:][:punct:] ]' then
    canonical:=regexp_replace(replace(term,'&','and'),'[^[:alnum:]]','','g');return next 'identifier:'||canonical;
  end if;
end $$;
revoke all on function app.private_invoice_term_aliases(text) from public,anon,authenticated,service_role;

-- Explicit printed-evidence provenance. Preserve raw evidence and derive the
-- labelled value plus every currency-bearing numeric candidate, even when the
-- extraction validator cannot resolve its amount. No whole workspace wall.
create function app.private_invoice_evidence_aliases(p_term text) returns setof text
language plpgsql immutable set search_path='' as $$
declare
  line text; payload text; candidate text[];
  amount_pattern text:=U&'[0-9]+(?:[., ''\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]+[0-9]+)*(?:[kmb])?';
  currency_pattern text;
begin
  currency_pattern:='(?:(?:(?:inr|usd|eur|gbp|aed|sgd|aud|cad|chf|rs\.?|rupees?|dollars?|euros?|pounds?)|'||U&'[\0024\00a2-\00a5\058f\060b\07fe-\07ff\09f2-\09f3\09fb\0af1\0bf9\0e3f\17db\20a0-\20c1\a838\fdfc\fe69\ff04\ffe0-\ffe1\ffe5-\ffe6\+011fdd-\+011fe0\+01e2ff\+01ecb0]'||') *[+−-]? *'||amount_pattern||'|'||amount_pattern||' *(?:(?:inr|usd|eur|gbp|aed|sgd|aud|cad|chf|rs\.?|rupees?|dollars?|euros?|pounds?)|'||U&'[\0024\00a2-\00a5\058f\060b\07fe-\07ff\09f2-\09f3\09fb\0af1\0bf9\0e3f\17db\20a0-\20c1\a838\fdfc\fe69\ff04\ffe0-\ffe1\ffe5-\ffe6\+011fdd-\+011fe0\+01e2ff\+01ecb0]'||'))';
  for line in select app.private_invoice_normalize(v) from regexp_split_to_table(p_term,E'[\\r\\n]+') v loop
    if length(line) between 1 and 3991 then return next 'evidence:'||line;end if;
    payload:=regexp_replace(line,'^[a-z_][a-z0-9_ .#%()/-]{0,80}[:=] *','');
    payload:=regexp_replace(payload,U&'^[a-z_][a-z_ .#%()/-]{0,80} +(?=[0-9+−\0024\00a2-\00a5\058f\060b\07fe-\07ff\09f2-\09f3\09fb\0af1\0bf9\0e3f\17db\20a0-\20c1\a838\fdfc\fe69\ff04\ffe0-\ffe1\ffe5-\ffe6\+011fdd-\+011fe0\+01e2ff\+01ecb0-])','');
    if length(payload) between 1 and 4000 then
      if line !~ '^(?:invoice +date|due(?: +date)?|date)(?![a-z])' and exists(select 1 from app.private_invoice_number_aliases(payload)) then
        return query select * from app.private_invoice_number_aliases(payload);
      else return query select * from app.private_invoice_term_aliases(payload);end if;
    end if;
    for candidate in select regexp_matches(line,currency_pattern,'g') loop
      return query select * from app.private_invoice_number_aliases(candidate[1]);
    end loop;
  end loop;
end $$;
revoke all on function app.private_invoice_evidence_aliases(text) from public,anon,authenticated,service_role;

-- Private-origin text is opaque to chat. Retain complete source and atomic
-- fields, including source dates, before any provider-bound request.
create function app.private_invoice_origin_aliases(p_term text) returns setof text
language plpgsql immutable set search_path='' as $$
declare term text; marker text[]; field text;
begin
  term:=app.private_invoice_normalize(regexp_replace(p_term,E'[\\r\\n]+',',','g'));
  term:=regexp_replace(term,'((?:the +)?(?:[0-9]{1,2}(?:st|nd|rd|th)?|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth|twenty[ -]+first|twenty[ -]+second|twenty[ -]+third|twenty[ -]+fourth|twenty[ -]+fifth|twenty[ -]+sixth|twenty[ -]+seventh|twenty[ -]+eighth|twenty[ -]+ninth|thirtieth|thirty[ -]+first)[ ./-]*(?:of +)?(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)|(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)[ ./-]*(?:the +)?(?:[0-9]{1,2}(?:st|nd|rd|th)?|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth|twenty[ -]+first|twenty[ -]+second|twenty[ -]+third|twenty[ -]+fourth|twenty[ -]+fifth|twenty[ -]+sixth|twenty[ -]+seventh|twenty[ -]+eighth|twenty[ -]+ninth|thirtieth|thirty[ -]+first)) *, *([''’ʼ]?[0-9]{4}|[''’ʼ]?[0-9]{2})(?![0-9])',E'\\1 \\2','g');
  marker:=regexp_match(term,'(?<![a-z0-9_])(?:(?:here|below|following|attached) +(?:is|are) +(?:(?:the|an?|my|our|this) +)?(?:invoices?|bills?(?! +gates)|receipts?)(?![a-z0-9_])|(?:forwarded|quoted|copied|pasted)(?: +(?:invoice|bill|receipt|message|text))* *[:>](?=.*(?:invoices?|bills?(?! +gates)|receipts?|[0-9][0-9,.]* *, *due +[0-9]))|(?:invoice|bill|receipt) *(?=[:,]))');if marker is null then return;end if;
  term:=substring(term from position(marker[1] in term));
  if length(term) between 1 and 3993 then return next 'origin:'||term;end if;
  return query select * from app.private_invoice_term_aliases(term);
  for field in select regexp_split_to_table(term,';|(?<![0-9]),|,(?![0-9])') loop
    field:=btrim(field);if left(field,length(marker[1]))=marker[1] then field:=substring(field from length(marker[1])+1);end if;
    field:=regexp_replace(field,'^[:> ]+','');field:=regexp_replace(field,U&'^[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]+|[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]+$','','g');field:=regexp_replace(field,'^(?:from|to|for) +','');
    field:=regexp_replace(field,'^(?:due(?: +date)?|invoice +date|bill +to|customer(?: +name)?|client(?: +name)?|amount|total) *(?::|=|is +)? *','');field:=regexp_replace(field,U&'^[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]+|[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]+$','','g');
    return query select * from app.private_invoice_term_aliases(field);
  end loop;
end $$;
revoke all on function app.private_invoice_origin_aliases(text) from public,anon,authenticated,service_role;

create function app.retain_private_invoice_terms(p_workspace_id uuid,p_document jsonb) returns void
language sql set search_path='' as $$
  insert into public.whatsapp_private_invoice_terms(workspace_id,term_hash,term)
  select distinct p_workspace_id,encode(sha256(convert_to(term,'UTF8')),'hex'),term from (
    select alias.term from jsonb_path_query(p_document,
      '$.** ? (@.type() == "string")') value
    cross join lateral app.private_invoice_term_aliases(value #>> '{}') alias(term)
    union all
    select alias.term from jsonb_path_query(p_document,'$.** ? (@.type() == "number")') value
    cross join lateral app.private_invoice_number_aliases(value #>> '{}') alias(term)
    union all
    select alias.term from jsonb_path_query(p_document,
      '$.**.printedEvidence.** ? (@.type() == "string")') value
    cross join lateral app.private_invoice_evidence_aliases(value #>> '{}') alias(term)
  ) terms where length(term) between 1 and 4000 and exists(select 1 from public.workspaces w where w.id=p_workspace_id) on conflict do nothing;
$$;
revoke all on function app.retain_private_invoice_terms(uuid,jsonb) from public,anon,authenticated,service_role;

create function app.retain_private_origin_terms(p_workspace_id uuid,p_text text) returns void
language sql set search_path='' as $$
 insert into public.whatsapp_private_invoice_terms(workspace_id,term_hash,term)
 select distinct p_workspace_id,encode(sha256(convert_to(term,'UTF8')),'hex'),term
 from app.private_invoice_origin_aliases(p_text) term where length(term) between 1 and 4000
 and exists(select 1 from public.workspaces w where w.id=p_workspace_id) on conflict do nothing;
$$;
revoke all on function app.retain_private_origin_terms(uuid,text) from public,anon,authenticated,service_role;

create function public.whatsapp_retain_private_chat_origin(p_workspace_id uuid,p_text text) returns boolean
language plpgsql security definer set search_path='' as $$
begin
 if p_workspace_id is null or p_text is null or length(p_text) not between 1 and 4000 then raise exception 'INVALID_PRIVATE_ORIGIN';end if;
 perform app.retain_private_origin_terms(p_workspace_id,p_text);return true;
end $$;
revoke all on function public.whatsapp_retain_private_chat_origin(uuid,text) from public,anon,authenticated;
grant execute on function public.whatsapp_retain_private_chat_origin(uuid,text) to service_role;

create function app.retain_private_review_terms() returns trigger
language plpgsql security definer set search_path='' as $$
declare value jsonb;
begin
 if tg_op<>'INSERT' and old.action->>'type'='invoice_review_draft' then
  value:=old.action;
  perform app.retain_private_invoice_terms(old.workspace_id,jsonb_build_object('invoice',value->'invoice','printedEvidence',value->'printedEvidence','ownerProvidedFacts',value->'ownerProvidedFacts'));
 end if;
 if tg_op<>'DELETE' and new.action->>'type'='invoice_review_draft' then
  value:=new.action;
  perform app.retain_private_invoice_terms(new.workspace_id,jsonb_build_object('invoice',value->'invoice','printedEvidence',value->'printedEvidence','ownerProvidedFacts',value->'ownerProvidedFacts'));
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $$;
revoke all on function app.retain_private_review_terms() from public,anon,authenticated,service_role;
create trigger retain_private_review_terms after insert or update of action or delete on public.whatsapp_pending_actions
 for each row execute function app.retain_private_review_terms();

create function app.retain_private_ledger_document(p_document jsonb) returns void
language sql set search_path='' as $$
 select app.retain_private_invoice_terms((p_document->>'workspace_id')::uuid,p_document||jsonb_build_object('linked_customer',
  (select jsonb_build_array(c.name,c.company_name,c.email,c.phone) from public.customers c
   where c.workspace_id=(p_document->>'workspace_id')::uuid and c.id=(p_document->>'customer_id')::uuid)));
$$;
revoke all on function app.retain_private_ledger_document(jsonb) from public,anon,authenticated,service_role;
create function app.retain_private_ledger_terms() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if tg_op<>'INSERT' then perform app.retain_private_ledger_document(to_jsonb(old));end if;
 if tg_op<>'DELETE' then perform app.retain_private_ledger_document(to_jsonb(new));end if;
 if tg_op='DELETE' then return old;end if;return new;
end $$;
revoke all on function app.retain_private_ledger_terms() from public,anon,authenticated,service_role;
create trigger retain_private_ledger_terms after insert or update or delete on public.invoices
 for each row execute function app.retain_private_ledger_terms();

create function app.retain_private_invoice_customer_terms() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if exists(select 1 from public.invoices i where i.workspace_id=old.workspace_id and i.customer_id=old.id) then
  perform app.retain_private_invoice_terms(old.workspace_id,jsonb_build_array(old.name,old.company_name,old.email,old.phone));
  if tg_op<>'DELETE' then perform app.retain_private_invoice_terms(new.workspace_id,jsonb_build_array(new.name,new.company_name,new.email,new.phone));end if;
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $$;
revoke all on function app.retain_private_invoice_customer_terms() from public,anon,authenticated,service_role;
create trigger retain_private_invoice_customer_terms before update of name,company_name,email,phone or delete on public.customers
 for each row execute function app.retain_private_invoice_customer_terms();

create function app.retain_private_chat_origin_terms() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if tg_op<>'INSERT' then perform app.retain_private_origin_terms(old.workspace_id,old.content);end if;
 if tg_op<>'DELETE' then perform app.retain_private_origin_terms(new.workspace_id,new.content);end if;
 if tg_op='DELETE' then return old;end if;return new;
end $$;
revoke all on function app.retain_private_chat_origin_terms() from public,anon,authenticated,service_role;
create trigger retain_private_owner_origin after insert or update of content or delete on public.owner_assistant_turns
 for each row execute function app.retain_private_chat_origin_terms();
create trigger retain_private_customer_origin after insert or update of content or delete on public.whatsapp_conversation_turns
 for each row execute function app.retain_private_chat_origin_terms();

-- No source scan or backfill under DDL locks. Watermarks are captured by
-- the first separately committed batch for each source after this DDL commits.
-- OLD/NEW triggers retain concurrent changes before and behind each cursor.
insert into public.whatsapp_private_invoice_backfill(source) values
 ('invoices'),('reviews'),('owner_quotes'),('customer_quotes');

create function app.backfill_private_invoice_terms(p_limit integer default 25) returns jsonb
language plpgsql security definer set search_path='' set lock_timeout='250ms' as $$
declare job public.whatsapp_private_invoice_backfill; row record; table_name text; key_type text;
 count_rows integer:=0; cursor_key text; has_more boolean; started timestamptz:=clock_timestamp();
begin
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'INVALID_BATCH_SIZE';end if;
 select * into job from public.whatsapp_private_invoice_backfill where not complete order by source for update skip locked limit 1;
 if not found then return jsonb_build_object('rows',0,'busy',exists(select 1 from public.whatsapp_private_invoice_backfill where not complete),
  'allComplete',not exists(select 1 from public.whatsapp_private_invoice_backfill where not complete));end if;
 table_name:=case job.source when 'invoices' then 'invoices' when 'reviews' then 'whatsapp_pending_actions'
  when 'owner_quotes' then 'owner_assistant_turns' when 'customer_quotes' then 'whatsapp_conversation_turns' end;
 key_type:=case when job.source='invoices' then 'uuid' else 'bigint' end;
 if job.upper_key is null then
  execute format('select id::text from public.%I order by id desc limit 1',table_name) into job.upper_key;
 end if;
 cursor_key:=coalesce(job.last_key,case when key_type='uuid' then '00000000-0000-0000-0000-000000000000' else '0' end);
 if job.upper_key is not null then
  for row in execute format('select id::text key,workspace_id,to_jsonb(s) doc from public.%I s where id>$1::%s and id<=$2::%s order by id limit $3',table_name,key_type,key_type)
   using cursor_key,job.upper_key,p_limit loop
   if job.source='invoices' then perform app.retain_private_ledger_document(row.doc);
   elsif job.source='reviews' and row.doc->'action'->>'type'='invoice_review_draft' then
    perform app.retain_private_invoice_terms(row.workspace_id,jsonb_build_object('invoice',row.doc->'action'->'invoice','printedEvidence',row.doc->'action'->'printedEvidence','ownerProvidedFacts',row.doc->'action'->'ownerProvidedFacts'));
   elsif job.source in ('owner_quotes','customer_quotes') then perform app.retain_private_origin_terms(row.workspace_id,row.doc->>'content');end if;
   cursor_key:=row.key;count_rows:=count_rows+1;
   exit when clock_timestamp()-started>=interval '500 milliseconds';
  end loop;
  execute format('select exists(select 1 from public.%I where id>$1::%s and id<=$2::%s)',table_name,key_type,key_type) into has_more using cursor_key,job.upper_key;
 else has_more:=false;end if;
 update public.whatsapp_private_invoice_backfill set last_key=cursor_key,upper_key=job.upper_key,complete=not has_more,updated_at=clock_timestamp()
  where source=job.source;
 return jsonb_build_object('source',job.source,'rows',count_rows,'complete',not has_more,
  'allComplete',not exists(select 1 from public.whatsapp_private_invoice_backfill where not complete));
end $$;
revoke all on function app.backfill_private_invoice_terms(integer) from public,anon,authenticated,service_role;

-- DDL locks end here. Run scripts/backfill-private-invoice-terms.mjs only after
-- this transaction commits. Every bounded batch is a separate transaction;
-- existing source tables take AccessShareLock only during a batch. The runner
-- sets lock_timeout before SELECT and statement_timeout before each command.
-- New private-term uniqueness conflicts can briefly serialize matching writes;
-- the runner's statement timeout bounds this contention and retries are safe.
commit;
